    private synchronized SecretKey getCurrentWrappingKey() throws IOException {
        SecretKey currentWrappingKey = getWrappingKey(CURRENT_MASTER);
        if (currentWrappingKey != null) {
            return currentWrappingKey;
        }

        try {
            KeyGenerator keyGenerator = KeyGenerator.getInstance(
                    KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore");
